'use strict';

var invalid = [];
var test;

// Static string...
test = {
	'code': [
		'var format = require( \'@stdlib/string/format\' );',
		'',
		'var str = format( \'hello world\' );'
	].join( '\n' ),
	'output': [
		'var format = require( \'@stdlib/string/format\' );',
		'',
		'var str = \'hello world\';'
	].join( '\n' ),
	'errors': [
		{
			'message': 'Unnecessary format call. No placeholders found in format string.',
			'type': 'CallExpression'
		}
	]
};
invalid.push( test );

// Nested in `new Error`...
test = {
	'code': [
		'var format = require( \'@stdlib/string/format\' );',
		'',
		'throw new Error( format( \'invalid argument.\' ) );'
	].join( '\n' ),
	'output': [
		'var format = require( \'@stdlib/string/format\' );',
		'',
		'throw new Error( \'invalid argument.\' );'
	].join( '\n' ),
	'errors': [
		{
			'message': 'Unnecessary format call. No placeholders found in format string.',
			'type': 'CallExpression'
		}
	]
};
invalid.push( test );

// Escaped percent only (no conversion; no autofix due to `%%` unescaping)...
test = {
	'code': [
		'var format = require( \'@stdlib/string/format\' );',
		'',
		'var str = format( \'100%%\' );'
	].join( '\n' ),
	'errors': [
		{
			'message': 'Unnecessary format call. No placeholders found in format string.',
			'type': 'CallExpression'
		}
	]
};
invalid.push( test );

// Extra arguments (no autofix to avoid dropping expressions with side effects)...
test = {
	'code': [
		'var format = require( \'@stdlib/string/format\' );',
		'',
		'var str = format( \'hello\', x );'
	].join( '\n' ),
	'errors': [
		{
			'message': 'Unnecessary format call. No placeholders found in format string.',
			'type': 'CallExpression'
		}
	]
};
invalid.push( test );

// Alias other than `format`...
test = {
	'code': [
		'var fmt = require( \'@stdlib/string/format\' );',
		'',
		'var str = fmt( \'static text\' );'
	].join( '\n' ),
	'output': [
		'var fmt = require( \'@stdlib/string/format\' );',
		'',
		'var str = \'static text\';'
	].join( '\n' ),
	'errors': [
		{
			'message': 'Unnecessary format call. No placeholders found in format string.',
			'type': 'CallExpression'
		}
	]
};
invalid.push( test );

// Inner scope resolving to outer require...
test = {
	'code': [
		'var format = require( \'@stdlib/string/format\' );',
		'',
		'function foo() {',
		'  return format( \'static text\' );',
		'}'
	].join( '\n' ),
	'output': [
		'var format = require( \'@stdlib/string/format\' );',
		'',
		'function foo() {',
		'  return \'static text\';',
		'}'
	].join( '\n' ),
	'errors': [
		{
			'message': 'Unnecessary format call. No placeholders found in format string.',
			'type': 'CallExpression'
		}
	]
};
invalid.push( test );


// EXPORTS //

module.exports = invalid;
